def partition_palindromes(s):
    result = []

    def split(start, pieces):
        if start == len(s):
            result.append(list(pieces))
            return
        for end in range(start + 1, len(s) + 1):
            piece = s[start:end]
            if piece == piece[::-1]:
                pieces.append(piece)
                split(end, pieces)
                pieces.pop()

    split(0, [])
    return result

