def find_paths(maze):
    n = len(maze)
    paths = []
    if maze[0][0] == 0 or maze[n - 1][n - 1] == 0:
        return paths
    visited = [[False] * n for _ in range(n)]
    moves = [("D", 1, 0), ("L", 0, -1), ("R", 0, 1), ("U", -1, 0)]

    def walk(r, c, path):
        if r == n - 1 and c == n - 1:
            paths.append(path)
            return
        visited[r][c] = True
        for letter, dr, dc in moves:
            nr, nc = r + dr, c + dc
            if 0 <= nr < n and 0 <= nc < n and maze[nr][nc] == 1 and not visited[nr][nc]:
                walk(nr, nc, path + letter)
        visited[r][c] = False

    walk(0, 0, "")
    return sorted(paths)

