def graph_coloring(n, edges, m):
    adjacency = [[] for _ in range(n)]
    for u, v in edges:
        adjacency[u].append(v)
        adjacency[v].append(u)
    colours = [0] * n

    def paint(node):
        if node == n:
            return True
        for colour in range(1, m + 1):
            if all(colours[neighbour] != colour for neighbour in adjacency[node]):
                colours[node] = colour
                if paint(node + 1):
                    return True
                colours[node] = 0
        return False

    return paint(0)

