def solve_sudoku(board):
    def allowed(r, c, digit):
        for i in range(9):
            if board[r][i] == digit or board[i][c] == digit:
                return False
            if board[3 * (r // 3) + i // 3][3 * (c // 3) + i % 3] == digit:
                return False
        return True

    def solve():
        for r in range(9):
            for c in range(9):
                if board[r][c] == ".":
                    for digit in "123456789":
                        if allowed(r, c, digit):
                            board[r][c] = digit
                            if solve():
                                return True
                            board[r][c] = "."
                    return False
        return True

    solve()
    return board
